settings.custom_css:
/* --- contador --- */
selector .elementor-accordion,
selector .e-n-accordion {
  counter-reset: faq;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

/* --- la tarjeta blanca con la barra roja --- */
selector .elementor-accordion-item,
selector .e-n-accordion-item {
  counter-increment: faq;
  background: #FFFFFF;
  border: none;
  border-left: 5px solid #FEB100;
  border-radius: 4px;
  box-shadow: 0 1px 3px rgba(11, 20, 45, 0.06);
  overflow: hidden;
}

/* --- la cabecera --- */
selector .elementor-tab-title,
selector .e-n-accordion-item-title {
  display: flex;
  align-items: center;
  gap: 0;
  min-height: 62px;
  padding: 0 32px 0 26px;
  background: transparent;
  border: none;
  list-style: none;
  cursor: pointer;
}

selector .e-n-accordion-item-title::marker,
selector .e-n-accordion-item-title::-webkit-details-marker {
  display: none;
  content: "";
}

/* --- el número rojo --- */
selector .elementor-tab-title::before,
selector .e-n-accordion-item-title::before {
  content: counter(faq, decimal-leading-zero);
  order: 1;
  flex: 0 0 auto;
  margin-right: 32px;
  font: normal normal 700 18px/1 Inter, sans-serif;
  color: #FEB100;
}

/* --- el texto de la pregunta --- */
selector .elementor-accordion-title,
selector .e-n-accordion-item-title-header {
  order: 2;
  flex: 1 1 auto;
}

selector .elementor-accordion-title,
selector .e-n-accordion-item-title-text {
  font: normal normal 600 17px/24px Inter, sans-serif;
  letter-spacing: 0;
  color: #1A1A1A;
  text-align: left;
}

/* --- el + a la derecha --- */
selector .elementor-accordion-icon,
selector .e-n-accordion-item-title-icon {
  order: 3;
  margin-left: auto;
  margin-right: 0;
  float: none;
  width: auto;
  font-size: 20px;
  color: #FEB100 !important;
}

selector .elementor-accordion-icon i,
selector .elementor-accordion-icon-opened i,
selector .elementor-accordion-icon-closed i,
selector .e-n-accordion-item-title-icon i,
selector .e-n-accordion-item-title-icon .e-opened i,
selector .e-n-accordion-item-title-icon .e-closed i {
  color: #FEB100 !important;
  font-size: 20px;
}

selector .elementor-accordion-icon svg,
selector .elementor-accordion-icon svg path,
selector .e-n-accordion-item-title-icon svg,
selector .e-n-accordion-item-title-icon svg path,
selector .e-n-accordion-item-title-icon .e-opened svg,
selector .e-n-accordion-item-title-icon .e-opened svg path,
selector .e-n-accordion-item-title-icon .e-closed svg,
selector .e-n-accordion-item-title-icon .e-closed svg path {
  width: 18px;
  height: 18px;
  fill: #FEB100 !important;
  stroke: #FEB100 !important;
}

/* --- el contenido desplegado --- */
selector .elementor-tab-content,
selector .e-n-accordion-item > .e-con {
  padding: 4px 32px 26px 84px;
  border: none;
  font: normal normal 400 15px/26px Inter, sans-serif;
  color: #3A4358;
}

selector .elementor-tab-content strong,
selector .e-n-accordion-item > .e-con strong {
  font-weight: 700;
  color: #0B142D;
}

@media (max-width: 767px) {
  selector .elementor-tab-title,
  selector .e-n-accordion-item-title {
    padding: 0 18px 0 16px;
    min-height: 56px;
  }
  selector .elementor-tab-title::before,
  selector .e-n-accordion-item-title::before {
    margin-right: 16px;
    font-size: 16px;
  }
  selector .elementor-accordion-title,
  selector .e-n-accordion-item-title-text {
    font-size: 15px;
    line-height: 21px;
  }
  selector .elementor-tab-content,
  selector .e-n-accordion-item > .e-con {
    padding: 4px 18px 20px 50px;
  }
}
